// Scene presets. The keys must match the "Scene" options in the form.
const SCENES = {
  'Clean studio (white background)':
    'on a seamless pure white background, soft diffused studio lighting, a subtle natural contact shadow, crisp e-commerce catalog style',
  'Lifestyle at home':
    'placed naturally in a bright, modern home setting that suits the product, soft window light, shallow depth of field, warm and inviting',
  'Outdoor, natural light':
    'outdoors in soft natural daylight, in surroundings that suit the product, gently blurred background, fresh and airy mood',
  'Luxury dark backdrop':
    'on a dark stone surface against a deep charcoal backdrop, dramatic rim lighting and soft reflections, premium magazine-ad look',
  'Social media flat lay':
    'shot top-down as a flat lay on a soft pastel background with a few complementary props, balanced composition with room for text',
};

const form = $('Product photo form').first().json;
const scene = SCENES[form['Scene']] ?? SCENES['Clean studio (white background)'];
const extra = (form['Extra instructions'] || '').trim();

const prompt = [
  `Professional advertising photo of the product in the reference image (${form['Product name']}), ${scene}.`,
  'Keep the product exactly as it is: same shape, proportions, colors, materials, logo and any text printed on it. Do not add new text or logos.',
  extra ? `Additional direction: ${extra}` : '',
].filter(Boolean).join(' ');

const ratio = form['Aspect ratio'] === 'Same as photo' ? 'auto' : form['Aspect ratio'];

return [{ json: { prompt, image_url: $input.first().json.data.publicUrl, aspect_ratio: ratio, resolution: form['Resolution'] } }];

